+  statSync,
+  fstatSync,
+  unlinkSync,
+  writeFileSync,
+} from 'node:fs';
+import { basename, dirname, join, resolve } from 'node:path';
+import { hostname, tmpdir } from 'node:os';
+import {
+  generateEd25519KeyPair,
+  signCanonical,
+  verifyCanonical,
+  type PrivateKeyBase64,
+} from './authority-signing.js';
+
+import {
+  HOST_RUN_FINAL_ASSISTANT_RESULT_CAP,
