+    deadlineMs: 5_000,
+    staleMs: 2_000,
+    pollMs: 10,
+    requireHolderToken: true,
+    classifyExistingLock: classifyManagedHostRunTerminalLock,
+    holderInfo: {
+      pid: process.pid,
+      hostname: hostname(),
+      command: `managed terminal ${paths.dir}`,
+      acquiredAt: new Date().toISOString(),
+      lockId: randomUUID(),
+      processStartTimeMs: currentProcessStartTimeMs(),
