+
+function appendEvent(paths: ManagedHostRunPaths, event: ManagedHostRunEvent): boolean {
+  assertArtifactRunId(paths, 'event', event.runId);
+  return withTerminalAuthorityLock(paths, () => {
+    if (readTerminal(paths)) return false;
